/* ============ SHARED HELPERS (theme verbatim) ============ */
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);
const nz=(t,f,p)=>Math.sin(t*f+p)*.5+Math.sin(t*f*2.3+p*2)*.3+Math.sin(t*f*.5+p*4)*.2;
function sizeC(c){const r=c.getBoundingClientRect(),d=devicePixelRatio||1;c.width=r.width*d;c.height=r.height*d;c.getContext('2d').setTransform(d,0,0,d,0,0);return[r.width,r.height]}

/* ============ EMBER BACKGROUND (theme verbatim behavior) ============ */
(function(){
  const c=$('#bgfx'),ctx=c.getContext('2d');
  const P=[];for(let i=0;i<70;i++){const s=Math.random();P.push({x:Math.random(),y:Math.random(),s:s,v:(.05+Math.random()*.14)/140});}
  const rm=matchMedia('(prefers-reduced-motion:reduce)').matches;
  function fr(){const[w,h]=sizeC(c);ctx.clearRect(0,0,w,h);
    P.forEach(p=>{if(!rm){p.y-=p.v;if(p.y<-.02)p.y=1.02;}
      const col=p.s>.5?'255,179,64':'57,214,255';
      ctx.fillStyle='rgba('+col+','+(.06+p.s*.12)+')';
      ctx.beginPath();ctx.arc(p.x*w,p.y*h,.8+p.s*1.6,0,7);ctx.fill();});
    requestAnimationFrame(fr);}
  fr();
})();

