function addElement(k,kind){
  if(state.mode==='reference'){toast('Reference is read-only · switch to Blank Builder');return}
  const data=curData();const ax=axisOf(data);
  if(kind==='media'){go('media');toast('Media slots live on the board · manage them here');return}
  if(kind==='sticky'){toast('Sticky note is on the board · click it to edit the text');return}
  const mid=Math.round((ax.y0+((ax.y1-ax.y0)/2))*12+5);
  const visibility=manualVisibilityForCategory(kind==='mile'?'usmle':k);
  const rec={id:nid(),t:kind==='mile'?'New milestone':'New '+CATS[k].n,cat:kind==='mile'?'usmle':k,
    mile:kind==='mile',s:miStr(mid),e:kind==='mile'?null:miStr(mid+3),vis:visibility.vis,visibilityState:visibility.visibilityState,loc:kind==='bar'?kcSiteDefault(k):'',origin:'manual',notes:'',lane:null};
  data.events.push(rec);state.saved=false;
  toast(kind==='mile'?'Milestone flag placed · drag it to its date':'Arrow generated · drag body to move · drag tip to resize');
  select(rec.id);
}
