/* ============ WIZARD ============ */
const WSTEPS=[
 {t:'IDENTITY',f:[['name','Student name','text'],['country','Medical school country','country'],['visa','Visa / status','text']]},
 {t:'SCHOOL + EXAMS',f:[['grad','Medical school graduation','month'],['s1a','Step 1 start','month'],['s1b','Step 1 end','month'],['s2a','Step 2 CK start','month'],['s2b','Step 2 CK end','month']]},
 {t:'US EXPERIENCE',f:[['cla','USCE clinic start','month'],['clb','USCE clinic end','month'],['tha','Teaching hospital start','month'],['thb','Teaching hospital end','month'],['ra','Research start','month'],['rb','Research end','month']]},
 {t:'STORY + TARGET',f:[['pt','Personal milestone','text'],['pd','Personal milestone month','month'],['ip','Interview program','text'],['idt','Interview month','month']]}
];
function renderWiz(){
  const host=$('#wizBody');if(!host)return;
  $('#wizDots').innerHTML=WSTEPS.map((s,i)=>'<span class="chip'+(i===state.wizStep?' em':'')+'" style="cursor:pointer" data-ws="'+i+'">'+(i+1)+' · '+s.t+'</span>').join('');
  $$('#wizDots .chip').forEach(c=>c.onclick=()=>{state.wizStep=+c.dataset.ws;renderWiz()});
  const st=WSTEPS[state.wizStep];
  host.innerHTML=st.f.map(f=>{
    const[k,l,ty]=f;const v=state.wiz[k]||'';
    if(ty==='country'){return '<label class="f"><span class="fl">'+l+'</span><select data-wk="'+k+'">'+COUNTRIES.map(c=>'<option'+(c===v?' selected':'')+'>'+c+'</option>').join('')+'</select></label>'}
    return '<label class="f"><span class="fl">'+l+'</span><input type="'+(ty==='month'?'month':'text')+'" data-wk="'+k+'" value="'+esc(v)+'"></label>';
  }).join('')
  +(state.wizStep===3?'<div style="display:flex;align-items:center;gap:10px"><div class="tglD'+(state.wiz.padv?' on':'')+'" id="wPadv"><i></i></div><span style="font-size:12px;color:var(--mid)">Share personal milestone with advisor</span></div>':'');
  $$('#wizBody [data-wk]').forEach(inp=>{inp.oninput=()=>{state.wiz[inp.dataset.wk]=inp.value;wizApply()}});
  const p=$('#wPadv');if(p)p.onclick=()=>{state.wiz.padv=!state.wiz.padv;p.classList.toggle('on');wizApply()};
}
function wizApply(){
  const w=state.wiz;const ev=state.user.events.filter(e=>e.origin!=='wizard');
  const push=(t,cat,s,e,mile,vis,loc)=>{if(!s)return;const legacyVis=vis||'public';ev.push({id:nid(),t:t,cat:cat,s:s,e:e||null,mile:!!mile,vis:legacyVis,visibilityState:{public:'INTERVIEWER_SAFE',full:'FULL_STORY',advisor:'ADVISOR_ONLY',student:'STUDENT_ONLY',hidden:'HIDDEN'}[legacyVis]||'ADVISOR_ONLY',loc:loc||'',origin:'wizard',notes:'',lane:null})};
  state.profile.name=w.name||'';state.profile.country=w.country||'';state.profile.visa=w.visa||'';
  push('Medical Degree','usmle',w.grad,null,true);
  if(w.s1a&&w.s1b)push('Step 1','usmle',w.s1a,w.s1b);
  if(w.s2a&&w.s2b)push('Step 2 CK','usmle',w.s2a,w.s2b);
  if(w.cla&&w.clb)push('USCE Clinic','cl',w.cla,w.clb);
  if(w.tha&&w.thb)push('Teaching Hospital','th',w.tha,w.thb);
  if(w.ra&&w.rb)push('Research','res',w.ra,w.rb);
  if(w.pt&&w.pd)push(w.pt,'personal',w.pd,null,true,w.padv?'advisor':'student');
  state.user.events=ev;
  state.user.interview={prog:w.ip||'',date:w.idt||'',label:w.ip?('MY BIG '+w.ip.toUpperCase()+' IV'):''};
  state.saved=false;renderBoards();renderHud();renderEvList();
}
$('#wizNext').onclick=()=>{if(state.wizStep<3){state.wizStep++;renderWiz()}else{wizApply();go('canvas');toast('Draft placed on the board · everything stays editable')}};
