function startParse(){
  if(state.uploadStage!=='idle')return;
  state.uploadStage='parsing';$('#parseWrap').style.display='block';
  const steps=['Reading 12 pages ▸','Finding experience sections ▸','Checking dates against the axis ▸','Building candidate events ▸'];
  const host=$('#parseSteps');host.innerHTML='';
  let i=0;const iv=setInterval(()=>{
    host.innerHTML+='<div>✓ '+steps[i]+'</div>';i++;
    if(i>=steps.length){clearInterval(iv);
      setTimeout(()=>{state.uploadStage='review';$('#parseWrap').style.display='none';$('#candWrap').style.display='block';renderCands();toast('6 candidates found · quarantined until you confirm')},500)}
  },600);
}
function renderCands(){
  const host=$('#candList');if(!host)return;
  host.innerHTML=state.candidates.map(c=>{
    const done=c.st!=='pending';
    return '<div class="candCard'+(c.st==='accepted'||c.st==='advisor'?' done':'')+(c.st==='aside'?' aside':'')+'">'
     +'<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><span class="dot" style="width:10px;height:10px;border-radius:2px;background:'+CATS[c.cat].c+'"></span>'
     +'<span class="candT">'+esc(c.t)+'</span><span class="chip '+c.cc+'">'+c.conf+'</span><span class="chip cy">'+c.src+'</span>'
     +'<span class="evd" style="font-family:var(--num);font-weight:600;font-size:11px;color:var(--dim);margin-left:auto">'+fmt(c.s)+' - '+fmt(c.e)+'</span></div>'
     +'<div class="candQ">'+esc(c.q)+'</div>'
     +(done?'<div class="chip '+(c.st==='aside'?'':'gn')+'">'+(c.st==='accepted'?'✓ ON BOARD':c.st==='advisor'?'◆ ADVISOR ONLY':'SET ASIDE')+'</div>'
       :'<div class="candRow">'
       +'<button class="btnD go sm" data-ca="accept" data-c="'+c.id+'">LOOKS RIGHT ▸</button>'
       +'<button class="btnD alt sm" data-ca="edit" data-c="'+c.id+'">FIX IT</button>'
       +'<button class="btnD alt sm" data-ca="advisor" data-c="'+c.id+'">ADVISOR-ONLY</button>'
       +'<button class="btnD alt sm" data-ca="hide" data-c="'+c.id+'">HIDE</button></div>')
     +'</div>';
  }).join('');
  const rev=state.candidates.filter(c=>c.st!=='pending').length;
  $('#candMeter').textContent=rev+' OF '+state.candidates.length+' REVIEWED';
  $$('#candList [data-ca]').forEach(b=>b.onclick=()=>candAct(b.dataset.c,b.dataset.ca));
}
function candAct(id,act){
  const c=state.candidates.find(x=>x.id===id);if(!c||c.st!=='pending')return;
  if(act==='hide'){c.st='aside';toast('Set aside · recoverable anytime');renderCands();renderHud();return}
  const candidateVisibility=act==='advisor'?'advisor':(c.cat==='personal'?'student':'public');
  const rec={id:nid(),t:c.t,cat:c.cat,mile:false,s:c.s,e:c.e,vis:candidateVisibility,visibilityState:{public:'INTERVIEWER_SAFE',advisor:'ADVISOR_ONLY',student:'STUDENT_ONLY'}[candidateVisibility],loc:c.loc,origin:'upload',notes:'',lane:null,src:c.src,q:c.q};
  state.user.events.push(rec);c.st=act==='advisor'?'advisor':'accepted';state.saved=false;
  toast(act==='advisor'?'Confirmed · advisor-only · ghosted on board':'Confirmed · arrow generated on the blank canvas');
  renderCands();renderBoards();renderHud();renderEvList();
  if(act==='edit'){state.mode='blank';$$('#modeSeg button').forEach(x=>x.classList.toggle('on',x.dataset.m==='blank'));go('canvas');select(rec.id)}
}

