function renderAdvisor(){
  const host=$('#advChecks');if(!host)return;
  const adata=dataOf(state.mode==='blank'?'blank':'demo');
  const comments=state.mode==='blank'?state.comments:state.demo.comments;
  const flags=state.mode==='blank'?state.flags:state.demo.flags;
  const isDemo=state.mode!=='blank'||(adata.events.length>0&&adata.events.every(event=>event.origin==='demo'));
  host.innerHTML=state.checks.map((c,i)=>'<div class="chkRow"><div class="tglD'+(c.on?' on':'')+'" data-chk="'+i+'"><i></i></div><span>'+c.t+'</span><span class="cst">'+(c.on?'DONE':'OPEN')+'</span></div>').join('');
  $$('#advChecks .tglD').forEach(t=>t.onclick=()=>{const c=state.checks[+t.dataset.chk];c.on=!c.on;renderAdvisor()});
  $('#advApprove').disabled=!state.checks.every(c=>c.on)||state.approved;
  $('#advComments').innerHTML=comments.length?comments.map(c=>'<div class="momD" data-cm="'+c.n+'"><div class="mts">◆ '+c.ts+'</div><div class="mb">'+esc(c.b)+'</div></div>').join(''):'<div class="chkRow"><span style="font-size:12px;color:var(--mid)">No advisor comments have been recorded for this draft.</span></div>';
  $('#advFlags').innerHTML=flags.length?flags.map((f,i)=>'<div class="chkRow"><span class="chip rd" style="letter-spacing:.12em">FLAG</span><span style="font-size:12.5px">'+esc(f.t)+'</span>'
    +'<button class="btnD alt sm" data-fl="'+i+'" style="margin-left:auto">'+(f.done?'✓ DISCUSSED':'MARK DISCUSSED')+'</button></div>').join(''):'<div class="chkRow"><span style="font-size:12px;color:var(--mid)">No review flags have been recorded.</span></div>';
  $$('#advFlags [data-fl]').forEach(b=>b.onclick=()=>{flags[+b.dataset.fl].done=true;renderAdvisor()});
  const pairs=overlapPairs(adata.events);
  const cheat=$('#advCheat');
  if(cheat){cheat.innerHTML=(isDemo
    ?'<div class="chkRow"><span class="chip cy">DEMO STORY ARC</span><span style="font-size:12px">Sample-only coaching structure. Verify every claim with the student before use.</span></div>'
    :'<div class="chkRow"><span class="chip cy">STORY ARC</span><span style="font-size:12px">'+(adata.events.length?adata.events.length+' student-entered or confirmed events are ready for advisor interpretation.':'No verified events yet. Advisor interpretation begins after the student adds or confirms content.')+'</span></div>')
   +(pairs.length?pairs.map(p=>'<div class="chkRow"><span class="chip em">OVERLAP</span><span style="font-size:12px">'+esc(p.a)+' × '+esc(p.b)+' · '+p.m+' months'+(p.pers?' · personal context':'')+'</span></div>').join('')
     :'<div class="chkRow"><span class="chip">OVERLAP</span><span style="font-size:12px;color:var(--mid)">No overlapping events on the current board</span></div>');}
  const qs=$('#advQs');
  const questions=isDemo?DEMO_QUESTIONS:legacyPracticeQuestions(adata.events);
  if(qs){qs.innerHTML=questions.length?questions.map((x,i)=>'<button class="candCard" data-q="'+i+'" style="width:100%;text-align:left;cursor:pointer"><div class="candT" style="font-size:12.5px;font-weight:600">'+esc(x.q)+'</div><div class="chip cy" style="margin-top:8px">CLICK TO HIGHLIGHT ON BOARD</div></button>').join(''):'<div class="chkRow"><span style="font-size:12px;color:var(--mid)">No interviewer practice questions can be generated from the current disclosure-safe events.</span></div>';
    qs.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{
      const qq=questions[+b.dataset.q];
      const ev=qq.eventId?adata.events.find(e=>e.id===qq.eventId):adata.events.find(e=>qq.re.test(e.t));
      if(!ev){toast('No matching board item yet · the gap itself is the answer');return}
      const el=document.querySelector('#boardAdvisor [data-ev="'+ev.id+'"]');
      if(el){el.classList.add('qhl');if(el.scrollIntoView)el.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>el.classList.remove('qhl'),1600)}
      toast('Highlighted · '+ev.t);
    });}
}
