     +'<div style="margin-top:14px;display:flex;gap:10px;align-items:center;flex-wrap:wrap">'
     +'<button class="btnD '+(blocked?'alt':'go')+' sm" data-ex="'+i+'"'+(blocked?' disabled':'')+'>EXPORT ▸</button>'
     +(blocked?'<span class="chip em">ADVISOR GATE PENDING</span>':'')
     +'</div></div>';
