/* ============ MODAL + TOAST ============ */
let legacyModalReturnFocus=null;
function setLegacyModalIsolation(active){['header','#rail','main'].forEach(selector=>{const element=$(selector);if(!element)return;element.inert=active;if(active)element.setAttribute('aria-hidden','true');else element.removeAttribute('aria-hidden');});}
function openModal(html,returnFocus){legacyModalReturnFocus=returnFocus||document.activeElement;const host=$('#modalIn'),backdrop=$('#modalBk');host.innerHTML=html;const title=host.querySelector('.subt');if(title){title.id='legacyModalTitle';backdrop.setAttribute('aria-labelledby',title.id);backdrop.removeAttribute('aria-label');}else backdrop.setAttribute('aria-label','Timeline dialog');setLegacyModalIsolation(true);backdrop.classList.add('on');backdrop.setAttribute('aria-hidden','false');requestAnimationFrame(()=>host.querySelector('button,input,select,textarea,[tabindex]:not([tabindex="-1"])')?.focus())}
function closeModal(){const backdrop=$('#modalBk');backdrop.classList.remove('on');backdrop.setAttribute('aria-hidden','true');backdrop.removeAttribute('aria-labelledby');backdrop.setAttribute('aria-label','Timeline dialog');setLegacyModalIsolation(false);const target=legacyModalReturnFocus,returnCategory=target?.dataset?.ck,returnSlot=target?.dataset?.slot;legacyModalReturnFocus=null;if(state.selCat){state.selCat=null;renderBoards()}const restored=target&&target.isConnected?target:returnCategory?document.querySelector('#boardMain [data-ck="'+returnCategory+'"]'):returnSlot?document.querySelector('#boardMain [data-slot="'+returnSlot+'"]'):null;if(restored)restored.focus()}
$('#modalBk').onclick=e=>{if(e.target.id==='modalBk')closeModal()};
document.addEventListener('keydown',e=>{const backdrop=$('#modalBk');if(!backdrop.classList.contains('on')||backdrop.dataset.modalOwner==='409')return;if(e.key==='Escape'){e.preventDefault();closeModal();return}if(e.key!=='Tab')return;const focusable=$$('#modalIn button:not([disabled]),#modalIn input:not([disabled]),#modalIn select:not([disabled]),#modalIn textarea:not([disabled]),#modalIn [tabindex]:not([tabindex="-1"])');if(!focusable.length){e.preventDefault();return}const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}},true);
let toastT=null;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('on');clearTimeout(toastT);toastT=setTimeout(()=>t.classList.remove('on'),2600)}

